export const meta = {
  purpose:
    "How many rules there are for a folder: items per file and per scope, how many load at launch, how many are written by hand and how many are generated by mike, plus bytes and estimated tokens. Run it before and after a consolidation to say how many were left.",
  params: { folder: "optional (default: the caller's folder)", max: "files listed, default 40" },
  returns: "{folder, total:{files, items, atLaunch, generatedByMike, written}, perScope:{scope:{files,items}}, perFile:['<items> items <scope> <loads> <path> (<kind> <n>, ...)'], sizes, launch}",
  example: 'await scripts.run("count")',
};

export default async function ({ rules }, { folder, max = 40 } = {}) {
  const r = await rules.count(folder, { max });
  const home = process.env.HOME || "";
  const short = (p) => (home && p.startsWith(home + "/") ? "~" + p.slice(home.length) : p);
  r.perFile = r.perFile.map((f) => `${f.items} items ${f.scope} ${f.loads} ${short(f.path)} (${Object.entries(f.kinds).map(([k, n]) => k + " " + n).join(", ")})${f.generated ? " generated by mike" : ""}`);
  return r;
}
